import Foundation

public struct PrivacyFilter {
    /// Mirrors the conservative pasteboard-type exclusions used by Maccy.
    public static let defaultBlockedTypeNames: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "net.antelle.keeweb"
    ]

    public let blockedTypeNames: Set<String>

    public init(blockedTypeNames: Set<String> = PrivacyFilter.defaultBlockedTypeNames) {
        self.blockedTypeNames = blockedTypeNames
    }

    public func allows(typeNames: Set<String>) -> Bool {
        blockedTypeNames.isDisjoint(with: typeNames)
    }
}
